struct Node;

/// The hosts this node's HTTPClient handle is scoped to. The handle enforces
/// this at the crossing, where a violation is a trap. We check it first so one
/// out-of-scope URL becomes a recorded failure instead of aborting the run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Bounds the work one run can ask for, whatever the input list holds.
const MAX_SUBSCRIPTIONS: usize = 32;

/// Bounds the length of error text copied into the batch.
const MAX_ERROR_CHARS: usize = 512;

/// Accepts only `https://<allowed-host>[:port][/...]`. Anything ambiguous
/// (userinfo, brackets, whitespace, control characters, odd ports) is refused.
fn in_scope(url: &str) -> bool {
    if url.chars().any(|c| c.is_control() || c.is_whitespace() || c == '\\') {
        return false;
    }
    let rest = match url.strip_prefix("https://") {
        Some(r) => r,
        None => return false,
    };
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    if authority.contains('@') || authority.contains('[') {
        return false;
    }
    let (host, port) = match authority.split_once(':') {
        Some((h, p)) => (h, Some(p)),
        None => (authority, None),
    };
    if let Some(p) = port {
        if p.is_empty() || !p.chars().all(|c| c.is_ascii_digit()) {
            return false;
        }
    }
    ALLOWED_HOSTS
        .iter()
        .any(|allowed| host.eq_ignore_ascii_case(allowed))
}

fn bounded(text: String) -> String {
    text.chars().take(MAX_ERROR_CHARS).collect()
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();
        let mut seen: Vec<String> = Vec::new();

        for url in subscriptions.urls.into_iter().take(MAX_SUBSCRIPTIONS) {
            if seen.iter().any(|s| s == &url) {
                continue;
            }
            seen.push(url.clone());

            if !in_scope(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url outside this node's host scope".to_string(),
                });
                continue;
            }

            match crate::aap::caps::http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument {
                    url,
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url,
                    error: bounded(error),
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

